#include <bits/stdc++.h>
using namespace std;

static const long long CAPM = 20000000LL;
static const long long CAPL = 25000000LL;

struct Item { string name; int q; long long v, m, l; };

int n;
Item items[12];
long long bestVal;
int bestSol[12], curSol[12];
chrono::steady_clock::time_point startTime;
bool timeUp;

void checkTime() {
    if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-startTime).count()>900)
        timeUp=true;
}
long long callCount=0;

double fractionalBound(int idx, double cap, const double* w, const double* val, const int* qi, int cnt, double curVal) {
    double ub = curVal, rem = cap;
    for(int i=0;i<cnt;i++){
        double tw = w[i]*qi[i];
        if(tw <= rem+1e-9){ ub += val[i]; rem -= tw; }
        else {
            if(w[i]>1e-12){ double f=min(rem/w[i],(double)qi[i]); ub+=val[i]/qi[i]*f; }
            else ub += val[i];
            break;
        }
    }
    return ub;
}

double lagBound(int idx, long long rm, long long rl, long long cv, double lam) {
    int cnt=n-idx;
    int ord[12]; double w[12],val[12],ratio[12]; int qi[12];
    for(int i=0;i<cnt;i++){
        int j=idx+i;
        w[i]=(double)items[j].m+lam*(double)items[j].l;
        val[i]=(double)items[j].v*items[j].q;
        qi[i]=items[j].q;
        ratio[i]=(w[i]>1e-12)?(double)items[j].v/w[i]:1e18;
        ord[i]=i;
    }
    sort(ord,ord+cnt,[&](int a,int b){return ratio[a]>ratio[b];});
    double cap=(double)rm+lam*(double)rl, ub=(double)cv, rem=cap;
    for(int ii=0;ii<cnt;ii++){
        int i=ord[ii]; double tw=w[i]*qi[i];
        if(tw<=rem+1e-9){ub+=val[i];rem-=tw;}
        else{if(w[i]>1e-12){double f=min(rem/w[i],(double)qi[i]);ub+=(double)items[idx+i].v*f;}else ub+=val[i];break;}
    }
    return ub;
}

double upperBound(int idx, long long rm, long long rl, long long cv) {
    double best=lagBound(idx,rm,rl,cv,0.0);
    best=min(best,lagBound(idx,rm,rl,cv,1e6));
    double lo=0,hi=200;
    for(int it=0;it<25;it++){
        double m1=lo+(hi-lo)/3,m2=hi-(hi-lo)/3;
        double v1=lagBound(idx,rm,rl,cv,m1),v2=lagBound(idx,rm,rl,cv,m2);
        best=min(best,min(v1,v2));
        if(v1<v2)hi=m2;else lo=m1;
    }
    best=min(best,lagBound(idx,rm,rl,cv,(lo+hi)/2));
    return best;
}

void solve(int idx, long long rm, long long rl, long long cv) {
    if(timeUp)return;
    if(idx==n){if(cv>bestVal){bestVal=cv;memcpy(bestSol,curSol,sizeof(bestSol));}return;}
    if(++callCount%8000==0)checkTime();
    if(timeUp)return;
    if(upperBound(idx,rm,rl,cv)<=(double)bestVal+0.5)return;
    long long maxM=(items[idx].m>0)?rm/items[idx].m:(long long)items[idx].q;
    long long maxL=(items[idx].l>0)?rl/items[idx].l:(long long)items[idx].q;
    int mx=(int)min({(long long)items[idx].q,maxM,maxL});
    for(int k=mx;k>=0;k--){
        curSol[idx]=k;
        solve(idx+1,rm-k*items[idx].m,rl-k*items[idx].l,cv+k*items[idx].v);
        if(timeUp)return;
    }
    curSol[idx]=0;
}

int main(){
    startTime=chrono::steady_clock::now();
    string input((istreambuf_iterator<char>(cin)),istreambuf_iterator<char>());
    vector<pair<string,vector<long long>>>entries;
    size_t pos=0;
    while(true){
        pos=input.find('"',pos);if(pos==string::npos)break;
        size_t end=input.find('"',pos+1);string key=input.substr(pos+1,end-pos-1);pos=end+1;
        size_t br=input.find('[',pos);if(br==string::npos)break;
        size_t br2=input.find(']',br);string arr=input.substr(br+1,br2-br-1);pos=br2+1;
        vector<long long>nums;stringstream ss(arr);string tok;
        while(getline(ss,tok,',')){long long v=0;for(char c:tok)if(c>='0'&&c<='9')v=v*10+(c-'0');nums.push_back(v);}
        if(nums.size()==4)entries.push_back({key,nums});
    }
    n=entries.size();
    for(int i=0;i<n;i++){items[i]={entries[i].first,(int)entries[i].second[0],entries[i].second[1],entries[i].second[2],entries[i].second[3]};}

    // Try multiple sort orders
    bestVal=-1;memset(bestSol,0,sizeof(bestSol));
    auto tryOrder=[&](vector<int>&ord){
        Item sorted[12];for(int i=0;i<n;i++)sorted[i]=items[ord[i]];
        memcpy(items,sorted,sizeof(Item)*n);
        memset(curSol,0,sizeof(curSol));
        // Greedy
        long long rm=CAPM,rl=CAPL,gv=0;int gs[12]={};
        for(int i=0;i<n;i++){
            long long mM=(items[i].m>0)?rm/items[i].m:items[i].q;
            long long mL=(items[i].l>0)?rl/items[i].l:items[i].q;
            int t=(int)min({(long long)items[i].q,mM,mL});
            gs[i]=t;rm-=t*items[i].m;rl-=t*items[i].l;gv+=t*items[i].v;
        }
        if(gv>bestVal){bestVal=gv;memcpy(bestSol,gs,sizeof(bestSol));}
        timeUp=false;callCount=0;
        solve(0,CAPM,CAPL,0);
    };

    vector<int>ord(n);iota(ord.begin(),ord.end(),0);
    // Sort by combined density
    sort(ord.begin(),ord.end(),[](int a,int b){
        double da=(double)items[a].v/max(1.0,max(items[a].m/20.0,items[a].l/25.0));
        double db=(double)items[b].v/max(1.0,max(items[b].m/20.0,items[b].l/25.0));
        return da>db;
    });
    tryOrder(ord);

    if(!timeUp){
        sort(ord.begin(),ord.end(),[](int a,int b){return items[a].q<items[b].q;});
        tryOrder(ord);
    }

    cout<<"{\n";
    for(int i=0;i<n;i++){cout<<" \""<<items[i].name<<"\": "<<bestSol[i];if(i<n-1)cout<<",";cout<<"\n";}
    cout<<"}\n";
}
